namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Room { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;

    public int InstructorId { get; set; }
    public Instructor Instructor { get; set; } = null!;
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Study of numbers, structures, and abstract patterns." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Study of literature, writing, and critical analysis." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events, societies, and civilizations." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 40 papers in top-tier conferences and holds two patents.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Professor", Bio = "Dr. Martinez is a leading researcher in abstract algebra with 20 years of teaching experience. He has authored three widely-used textbooks.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Assistant Professor", Bio = "Dr. Johnson studies quantum mechanics and particle physics. She completed postdoctoral work at CERN before joining the faculty.", Email = "sjohnson@university.edu" },
            new() { Id = 4, Name = "Prof. David Kim", Title = "Professor", Bio = "Prof. Kim is an award-winning author and literary critic. His essays on modern American fiction have appeared in The New Yorker and The Atlantic.", Email = "dkim@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Wright", Title = "Associate Professor", Bio = "Dr. Wright is a historian of early modern Europe with a focus on the social history of science and technology.", Email = "ewright@university.edu" },
            new() { Id = 6, Name = "Dr. James Park", Title = "Senior Lecturer", Bio = "Dr. Park has extensive industry experience in software engineering and brings practical insights to his courses on programming and databases.", Email = "jpark@university.edu" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science covering computational thinking, basic programming in Python, data representation, and an overview of major CS sub-fields.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Tech Hall 201", IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "In-depth study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Tech Hall 305", IsFeatured = true, DepartmentId = 1, InstructorId = 6 },
            new() { Id = 3, Code = "CS 420", Title = "Database Systems", Description = "Relational database design, SQL, transaction processing, indexing, and an introduction to NoSQL systems. Includes a semester-long project building a full-stack application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Hall 110", IsFeatured = false, DepartmentId = 1, InstructorId = 6 },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations and geometry.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Science Center 402", IsFeatured = false, DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and homomorphisms. Explores symmetry in mathematical structures and lays the groundwork for advanced study in algebra and number theory.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Science Center 410", IsFeatured = false, DepartmentId = 2, InstructorId = 2 },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, conservation of energy and momentum, rotational motion, fluid mechanics, and oscillations. Calculus-based.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Physics Lab 101", IsFeatured = true, DepartmentId = 3, InstructorId = 3 },
            new() { Id = 7, Code = "PHYS 305", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, hydrogen atom, spin, and perturbation theory. Prerequisites: PHYS 101, MATH 201.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Physics Lab 210", IsFeatured = false, DepartmentId = 3, InstructorId = 3 },
            new() { Id = 8, Code = "ENG 110", Title = "College Writing", Description = "Develops fluency in academic writing through close reading, analytical essays, peer review, and revision. Emphasizes clarity, argumentation, and evidence-based reasoning.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Humanities 220", IsFeatured = false, DepartmentId = 4, InstructorId = 4 },
            new() { Id = 9, Code = "ENG 350", Title = "American Literature: 1900–Present", Description = "Survey of American literary movements from modernism to contemporary fiction. Authors include Fitzgerald, Morrison, Pynchon, and Díaz.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 310", IsFeatured = true, DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, trade networks, and cultural exchanges from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", Room = "Liberal Arts 105", IsFeatured = false, DepartmentId = 5, InstructorId = 5 },
            new() { Id = 11, Code = "HIST 260", Title = "History of Science & Technology", Description = "Explores the development of scientific thought and technological innovation from the Scientific Revolution to the digital age, examining social, political, and economic contexts.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Liberal Arts 202", IsFeatured = true, DepartmentId = 5, InstructorId = 5 },
        ];

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);
}

