@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Browse Courses</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<div class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or keyword…"
               @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name (@dept.Abbreviation)</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@if (FilteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in FilteredCourses)
                {
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@course.Department.Abbreviation</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredCourses.Count course(s)</p>
}

@code {
    [SupplyParameterFromQuery(Name = "department")]
    public int? InitialDepartmentId { get; set; }

    private List<Department> Departments { get; set; } = [];
    private List<Course> FilteredCourses { get; set; } = [];

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    private string SearchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int SelectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        Departments = Catalog.GetDepartments();
        _selectedDepartmentId = InitialDepartmentId ?? 0;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        FilteredCourses = Catalog.SearchCourses(_searchTerm, deptFilter);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        ApplyFilters();
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Submit Enrollment Request</h1>

<div class="row">
    <div class="col-lg-7">
        <EditForm Model="Request" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" class="form-control" @bind-Value="Request.StudentName" />
                <ValidationMessage For="() => Request.StudentName" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" class="form-control" @bind-Value="Request.StudentId" />
                <ValidationMessage For="() => Request.StudentId" />
                <div class="form-text">6–12 alphanumeric characters (e.g., STU12345)</div>
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Request.CourseId">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in AllCourses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Request.CourseId" />
            </div>

            <button type="submit" class="btn btn-success">Submit Request</button>
            <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
    <div class="col-lg-5">
        <div class="card bg-light">
            <div class="card-body">
                <h5 class="card-title">How Enrollment Works</h5>
                <ol class="mb-0">
                    <li>Fill out the form with your name and student ID.</li>
                    <li>Select the course you'd like to enroll in.</li>
                    <li>Submit your request — you'll receive a confirmation.</li>
                    <li>The registrar's office will process your request within 2 business days.</li>
                </ol>
            </div>
        </div>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Request { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private List<Course> AllCourses { get; set; } = [];

    protected override void OnInitialized()
    {
        AllCourses = Catalog.GetAllCourses();
        if (PreselectedCourseId.HasValue && Request.CourseId == 0)
        {
            Request.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Request.CourseId);
        Submitted = true;
        SubmittedCourseName = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
    }

    private bool Submitted { get; set; }
    private string SubmittedCourseName { get; set; } = string.Empty;
}

